x_938076_backup_0_backup_scripts.script:
 var excelRowArray = [];
 var rejectedTrades = [];

 //getting the attachment
 var getAttachment = new GlideRecord('sys_attachment');
 getAttachment.addEncodedQuery('table_sys_id=' + '78271e1347c12200e0ef563dbb9a7109');
 getAttachment.query();
 if (getAttachment.next()) {
     var attachmentRec = getAttachment.getValue('sys_id');
 }
 //getting attachment

 var attachment = new GlideSysAttachment(); //method to get the contents of the attachment
 var attachmentDetails = attachment.getContentStream(attachmentRec); //getting content of the EXcel

 var parser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
 parser.setSource(attachmentDetails); //setting the source to parse the content from the stream

 var getSheet = parser.getSheetNames(); //getting the sheet name to fetch details
 parser.setSheetName(getSheet); //setting the sheet to parse

 if (parser.parse()) { //converting into readable format using parse

     while (parser.next()) { //iterating over each row
         var getRows = parser.getRow(); //reading row by row
		 getRows.business = 'HSBC';
         var rowObj = JSON.stringify(getRows); //holds the rows of Excel as comma sepearated
         excelRowArray.push(rowObj + '');

     }
 }

 gs.info(excelRowArray.toString());
